import Dispatch
final class CompletedCounter {
    private let queue = DispatchQueue(label: "practice.counter")
    private var stored = 0
    func claim(limit: Int) -> Bool {
        queue.sync {
            guard stored < limit else { return false }
            stored += 1
            return true
        }
    }
    func increment() { queue.sync { stored += 1 } }
    func read() -> Int { queue.sync { stored } }
}
let counter = CompletedCounter()
print(counter.claim(limit: 1))
print(counter.claim(limit: 1))
print(counter.read())
let empty = CompletedCounter()
print(empty.claim(limit: 0))

Вывод true, false, 1, false. Проверка и изменение составляют одну операцию; пустой лимит не меняет состояние.

import Dispatch
final class PracticeBudget {
    private let queue = DispatchQueue(label: "practice.budget")
    private var remaining: Int
    init(remaining: Int) { self.remaining = remaining }
    func consume() -> Bool {
        queue.sync {
            guard remaining > 0 else { return false }
            remaining -= 1
            return true
        }
    }
    func read() -> Int { queue.sync { remaining } }
}
let budget = PracticeBudget(remaining: 2)
print(budget.consume())
print(budget.consume())
